-- Grok, Cursor and X Premium Merge Into One Subscription, and Claude and GPT Now Cost Extra in Cursor
-- Источник: https://x.ai/news/x-subscription. Идемпотентно.

DELETE FROM news WHERE slug = 'x-subscription-grok-cursor-bundle';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('x-subscription-grok-cursor-bundle', 'en', 'business', $t$Business$t$, '#f5a623', $t$xAI / Cursor$t$, $t$https://x.ai/news/x-subscription$t$, '2026-10-12', $t$Grok, Cursor and X Premium Merge Into One Subscription, and Claude and GPT Now Cost Extra in Cursor$t$, $t$SpaceXSI launched The X Subscription on October 12, bundling Grok, Cursor and X Premium into one plan from $8 to $200 a month with a shared weekly usage pool. New Cursor customers start on it, and Claude, GPT and other outside models are no longer included: they are billed at API list prices from prepaid credit.$t$, $t$<p>SpaceXSI, the company that owns Grok and Cursor, launched <strong>The X Subscription</strong> on October 12. It puts Grok, the Grok bot, <strong>Cursor</strong> and X Premium on a single plan, in five tiers: Free, Plus at $8, Premium at $30, Super at $100 and Ultra at $200 a month.</p>
<h2>One usage pool for Grok and Cursor</h2>
<p>Grok and Cursor now draw on the same weekly usage allowance. What you spend chatting with Grok is no longer separate from what you spend coding in Cursor, so heavy users of one have less left for the other.</p>
<h2>The catch for Cursor users</h2>
<p>New Cursor customers start on The X Subscription. Cursor's help pages state that third-party models in Cursor, such as <strong>Claude</strong> or <strong>GPT</strong>, are not included in the plan. They are billed at API list prices and paid from prepaid credit. People who already have a Cursor plan can keep it. Switching to the new subscription is optional, but Cursor says it cannot be undone.</p>
<h2>Why it matters</h2>
<p>For many developers the reason to use Cursor has been easy access to Claude and GPT models inside one editor for a flat monthly price. Under the new bundle, that flat price covers Grok and Cursor's own models, while Claude and GPT become pay-as-you-go. If you code mostly with Claude or GPT, compare what you would spend at API prices before switching, or stay on your current Cursor plan while you can. If Grok and Cursor's own models are enough for you, the bundle adds X Premium and Grok on top of the editor.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('x-subscription-grok-cursor-bundle', 'es', 'business', $t$Negocios$t$, '#f5a623', $t$xAI / Cursor$t$, $t$https://x.ai/news/x-subscription$t$, '2026-10-12', $t$Grok, Cursor y X Premium se fusionan en una sola suscripción, y Claude y GPT ahora cuestan extra en Cursor$t$, $t$SpaceXSI lanzó The X Subscription el 12 de octubre, agrupando Grok, Cursor y X Premium en un solo plan de entre $8 y $200 al mes con un fondo de uso semanal compartido. Los nuevos clientes de Cursor comienzan con este plan, y Claude, GPT y otros modelos externos ya no están incluidos: se facturan a precios de lista de la API con crédito prepagado.$t$, $t$<p>SpaceXSI, la empresa propietaria de Grok y Cursor, lanzó <strong>The X Subscription</strong> el 12 de octubre. Reúne a Grok, el bot Grok, <strong>Cursor</strong> y X Premium en un solo plan, en cinco niveles: Free, Plus a $8, Premium a $30, Super a $100 y Ultra a $200 al mes.</p>
<h2>Un fondo de uso compartido para Grok y Cursor</h2>
<p>Grok y Cursor ahora comparten el mismo límite de uso semanal. Lo que se gasta conversando con Grok ya no es independiente de lo que se gasta programando en Cursor, de modo que quienes usan mucho uno de los dos tienen menos disponible para el otro.</p>
<h2>La trampa para los usuarios de Cursor</h2>
<p>Los nuevos clientes de Cursor comienzan directamente con The X Subscription. Las páginas de ayuda de Cursor indican que los modelos de terceros en Cursor, como <strong>Claude</strong> o <strong>GPT</strong>, no están incluidos en el plan. Se facturan a precios de lista de la API y se pagan con crédito prepagado. Quienes ya tengan un plan de Cursor pueden conservarlo. Cambiar a la nueva suscripción es opcional, pero Cursor advierte que no se puede revertir.</p>
<h2>Por qué importa</h2>
<p>Para muchos desarrolladores, la razón para usar Cursor ha sido el acceso fácil a los modelos de Claude y GPT dentro de un solo editor por un precio mensual fijo. Con el nuevo paquete, ese precio fijo cubre a Grok y a los modelos propios de Cursor, mientras que Claude y GPT pasan a un esquema de pago por uso. Si programas principalmente con Claude o GPT, conviene comparar cuánto gastarías a precios de API antes de cambiar, o mantener tu plan actual de Cursor mientras sea posible. Si los modelos propios de Grok y Cursor te resultan suficientes, el paquete suma X Premium y Grok además del editor.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('x-subscription-grok-cursor-bundle', 'de', 'business', $t$Wirtschaft$t$, '#f5a623', $t$xAI / Cursor$t$, $t$https://x.ai/news/x-subscription$t$, '2026-10-12', $t$Grok, Cursor und X Premium werden zu einem Abo zusammengelegt – Claude und GPT kosten in Cursor jetzt extra$t$, $t$SpaceXSI hat am 12. Oktober The X Subscription gestartet und bündelt Grok, Cursor und X Premium in einem Plan von $8 bis $200 im Monat mit einem gemeinsamen wöchentlichen Nutzungskontingent. Neue Cursor-Kunden starten automatisch damit, und Claude, GPT sowie andere externe Modelle sind nicht mehr enthalten: Sie werden zu API-Listenpreisen aus vorab aufgeladenem Guthaben abgerechnet.$t$, $t$<p>SpaceXSI, das Unternehmen hinter Grok und Cursor, hat am 12. Oktober <strong>The X Subscription</strong> gestartet. Damit werden Grok, der Grok-Bot, <strong>Cursor</strong> und X Premium in einem einzigen Plan zusammengefasst, in fünf Stufen: Free, Plus für $8, Premium für $30, Super für $100 und Ultra für $200 im Monat.</p>
<h2>Ein gemeinsames Nutzungskontingent für Grok und Cursor</h2>
<p>Grok und Cursor greifen nun auf dasselbe wöchentliche Nutzungskontingent zu. Was man beim Chatten mit Grok verbraucht, ist nicht mehr getrennt von dem, was man beim Programmieren mit Cursor verbraucht – wer das eine stark nutzt, hat also weniger für das andere übrig.</p>
<h2>Der Haken für Cursor-Nutzer</h2>
<p>Neue Cursor-Kunden starten direkt mit The X Subscription. Auf den Hilfeseiten von Cursor heißt es, dass Drittanbietermodelle in Cursor, etwa <strong>Claude</strong> oder <strong>GPT</strong>, nicht in dem Plan enthalten sind. Sie werden zu API-Listenpreisen abgerechnet und aus vorab aufgeladenem Guthaben bezahlt. Wer bereits einen Cursor-Plan hat, kann diesen behalten. Der Wechsel zum neuen Abo ist optional, lässt sich laut Cursor aber nicht rückgängig machen.</p>
<h2>Warum das wichtig ist</h2>
<p>Für viele Entwickler war der Grund, Cursor zu nutzen, der einfache Zugang zu Claude- und GPT-Modellen innerhalb eines Editors zu einem festen Monatspreis. Im neuen Bundle deckt dieser Festpreis nun Grok und Cursors eigene Modelle ab, während Claude und GPT nach Verbrauch abgerechnet werden. Wer überwiegend mit Claude oder GPT programmiert, sollte vor einem Wechsel vergleichen, was dies zu API-Preisen kosten würde, oder solange wie möglich beim aktuellen Cursor-Plan bleiben. Wer mit Groks eigenen Modellen und Cursor auskommt, erhält mit dem Bundle zusätzlich X Premium und Grok obendrauf.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('x-subscription-grok-cursor-bundle', 'ru', 'business', $t$Бизнес$t$, '#f5a623', $t$xAI / Cursor$t$, $t$https://x.ai/news/x-subscription$t$, '2026-10-12', $t$Grok, Cursor и X Premium объединяются в одну подписку, а Claude и GPT теперь стоят отдельно в Cursor$t$, $t$SpaceXSI 12 октября запустила The X Subscription, объединив Grok, Cursor и X Premium в один тарифный план стоимостью от $8 до $200 в месяц с общим недельным лимитом использования. Новые клиенты Cursor подключаются к ней по умолчанию, а Claude, GPT и другие сторонние модели больше не входят в подписку: они оплачиваются по прайс-листу API из предоплаченных кредитов.$t$, $t$<p>SpaceXSI, компания, которой принадлежат Grok и Cursor, 12 октября запустила <strong>The X Subscription</strong>. Она объединяет Grok, бота Grok, <strong>Cursor</strong> и X Premium в единый план с пятью уровнями: Free, Plus за $8, Premium за $30, Super за $100 и Ultra за $200 в месяц.</p>
<h2>Единый пул использования для Grok и Cursor</h2>
<p>Теперь Grok и Cursor используют один и тот же недельный лимит. То, что вы тратите на общение с Grok, больше не отделено от того, что вы тратите на написание кода в Cursor, поэтому активные пользователи одного сервиса получают меньше ресурса для другого.</p>
<h2>Подвох для пользователей Cursor</h2>
<p>Новые клиенты Cursor подключаются к The X Subscription по умолчанию. На страницах помощи Cursor указано, что сторонние модели в Cursor, такие как <strong>Claude</strong> или <strong>GPT</strong>, не включены в план. Они оплачиваются по прайс-листу API и списываются с предоплаченных кредитов. Те, у кого уже есть план Cursor, могут его сохранить. Переход на новую подписку необязателен, но в Cursor предупреждают, что его нельзя отменить.</p>
<h2>Почему это важно</h2>
<p>Для многих разработчиков главной причиной пользоваться Cursor был удобный доступ к моделям Claude и GPT внутри одного редактора за фиксированную ежемесячную плату. В рамках нового пакета эта фиксированная плата покрывает Grok и собственные модели Cursor, а Claude и GPT переходят на оплату по факту использования. Если вы в основном работаете с Claude или GPT, перед переходом сравните, во сколько обойдется использование по ценам API, либо оставайтесь на текущем плане Cursor, пока это возможно. Если же вам достаточно Grok и собственных моделей Cursor, новый пакет дополнительно дает X Premium и Grok поверх редактора.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('x-subscription-grok-cursor-bundle', 'ua', 'business', $t$Бізнес$t$, '#f5a623', $t$xAI / Cursor$t$, $t$https://x.ai/news/x-subscription$t$, '2026-10-12', $t$Grok, Cursor і X Premium об'єднуються в одну підписку, а Claude і GPT тепер коштують додатково в Cursor$t$, $t$SpaceXSI запустила The X Subscription 12 жовтня, об'єднавши Grok, Cursor і X Premium в один план вартістю від $8 до $200 на місяць зі спільним щотижневим лімітом використання. Нові клієнти Cursor одразу потрапляють на цей план, а Claude, GPT та інші сторонні моделі більше не входять до нього: вони оплачуються за цінами API з попередньо поповненого балансу.$t$, $t$<p>SpaceXSI, компанія, якій належать Grok і Cursor, запустила <strong>The X Subscription</strong> 12 жовтня. Вона об'єднує Grok, бота Grok, <strong>Cursor</strong> і X Premium в єдиний план із п'ятьма рівнями: Free, Plus за $8, Premium за $30, Super за $100 та Ultra за $200 на місяць.</p>
<h2>Єдиний пул використання для Grok і Cursor</h2>
<p>Grok і Cursor тепер використовують спільний щотижневий ліміт. Те, що ви витрачаєте на спілкування з Grok, більше не відокремлено від того, що ви витрачаєте на програмування в Cursor, тож активні користувачі одного сервісу матимуть менше ресурсу для іншого.</p>
<h2>Підводний камінь для користувачів Cursor</h2>
<p>Нові клієнти Cursor одразу починають із The X Subscription. На сторінках довідки Cursor зазначено, що сторонні моделі в Cursor, такі як <strong>Claude</strong> чи <strong>GPT</strong>, не входять до плану. Вони оплачуються за цінами зі списку API та списуються з попередньо поповненого балансу. Ті, хто вже має план Cursor, можуть його зберегти. Перехід на нову підписку є добровільним, але, за словами Cursor, скасувати його неможливо.</p>
<h2>Чому це важливо</h2>
<p>Для багатьох розробників причиною користуватися Cursor був зручний доступ до моделей Claude і GPT в одному редакторі за фіксовану щомісячну плату. За новою пропозицією ця фіксована плата покриває Grok і власні моделі Cursor, тоді як Claude і GPT переходять на оплату за фактичне використання. Якщо ви переважно програмуєте з Claude чи GPT, порівняйте, скільки це коштуватиме за цінами API, перш ніж переходити, або залишайтеся на поточному плані Cursor, поки є така можливість. Якщо вам достатньо Grok і власних моделей Cursor, новий пакет додає до редактора ще й X Premium та Grok.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('x-subscription-grok-cursor-bundle', 'he', 'business', $t$עסקים$t$, '#f5a623', $t$xAI / Cursor$t$, $t$https://x.ai/news/x-subscription$t$, '2026-10-12', $t$‏Grok, Cursor ו-X Premium מתמזגים למנוי אחד, וClaude ו-GPT עולים כעת תוספת תשלום ב-Cursor$t$, $t$SpaceXSI השיקה ב-12 באוקטובר את The X Subscription, שמאחדת את Grok, Cursor ו-X Premium לתוכנית אחת במחיר שבין $8 ל-$200 לחודש עם מכסת שימוש שבועית משותפת. לקוחות Cursor חדשים מתחילים בתוכנית הזו, ו-Claude, GPT ומודלים חיצוניים אחרים כבר לא נכללים בה: הם מחויבים לפי מחירי מחירון ה-API מתוך יתרת קרדיט ששולמה מראש.$t$, $t$<p>SpaceXSI, החברה שבבעלותה Grok ו-Cursor, השיקה ב-12 באוקטובר את <strong>The X Subscription</strong>. התוכנית מאחדת את Grok, בוט ה-Grok, <strong>Cursor</strong> ו-X Premium למנוי אחד, בחמש רמות: Free, Plus במחיר $8, Premium במחיר $30, Super במחיר $100 ו-Ultra במחיר $200 לחודש.</p>
<h2>מכסת שימוש אחת ל-Grok ול-Cursor</h2>
<p>Grok ו-Cursor שואבים כעת ממכסת שימוש שבועית משותפת. מה שמשתמש מוציא בשיחה עם Grok כבר לא נפרד ממה שהוא מוציא בכתיבת קוד ב-Cursor, כך שמשתמשים כבדים באחד מהם נשארים עם פחות מכסה לשני.</p>
<h2>הקאץ' עבור משתמשי Cursor</h2>
<p>לקוחות Cursor חדשים מתחילים ישירות ב-The X Subscription. דפי העזרה של Cursor מציינים כי מודלים של צד שלישי ב-Cursor, כגון <strong>Claude</strong> או <strong>GPT</strong>, אינם נכללים בתוכנית. הם מחויבים לפי מחירי מחירון ה-API ומשולמים מתוך יתרת קרדיט ששולמה מראש. מי שכבר נמצא בתוכנית Cursor קיימת יכול להישאר בה. המעבר למנוי החדש הוא אופציונלי, אך לפי Cursor לא ניתן לבטל אותו לאחר שבוצע.</p>
<h2>למה זה חשוב</h2>
<p>עבור מפתחים רבים, הסיבה להשתמש ב-Cursor הייתה גישה נוחה למודלים של Claude ו-GPT בתוך עורך אחד תמורת מחיר חודשי קבוע. במסגרת החבילה החדשה, המחיר הקבוע מכסה את Grok ואת המודלים של Cursor עצמה, בעוד ש-Claude ו-GPT הופכים לתשלום לפי שימוש. מי שכותב קוד בעיקר עם Claude או GPT מוזמן להשוות מראש כמה הוא היה מוציא לפי מחירי ה-API לפני שהוא עובר לתוכנית החדשה, או להישאר בתוכנית Cursor הנוכחית שלו כל עוד הדבר אפשרי. מי שהמודלים של Grok ו-Cursor עצמם מספיקים לו, החבילה מוסיפה עבורו גם את X Premium וגם את Grok מעל העורך.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('x-subscription-grok-cursor-bundle', 'fr', 'business', $t$Business$t$, '#f5a623', $t$xAI / Cursor$t$, $t$https://x.ai/news/x-subscription$t$, '2026-10-12', $t$Grok, Cursor et X Premium fusionnent en un seul abonnement, et Claude et GPT deviennent payants en supplément dans Cursor$t$, $t$SpaceXSI a lancé The X Subscription le 12 octobre, regroupant Grok, Cursor et X Premium dans un seul forfait allant de 8 $ à 200 $ par mois, avec un quota d'utilisation hebdomadaire partagé. Les nouveaux clients de Cursor démarrent sur ce forfait, et Claude, GPT et les autres modèles externes n'y sont plus inclus : ils sont facturés aux tarifs publics de l'API à partir d'un crédit prépayé.$t$, $t$<p>SpaceXSI, l'entreprise propriétaire de Grok et de Cursor, a lancé <strong>The X Subscription</strong> le 12 octobre. Ce forfait réunit Grok, le bot Grok, <strong>Cursor</strong> et X Premium en un seul plan, décliné en cinq niveaux : Free, Plus à 8 $, Premium à 30 $, Super à 100 $ et Ultra à 200 $ par mois.</p>
<h2>Un quota d'utilisation commun pour Grok et Cursor</h2>
<p>Grok et Cursor puisent désormais dans la même allocation d'utilisation hebdomadaire. Ce que vous dépensez en discutant avec Grok n'est plus distinct de ce que vous dépensez en codant dans Cursor, de sorte que les gros utilisateurs de l'un disposent de moins de marge pour l'autre.</p>
<h2>Le piège pour les utilisateurs de Cursor</h2>
<p>Les nouveaux clients de Cursor démarrent sur The X Subscription. Les pages d'aide de Cursor précisent que les modèles tiers utilisés dans Cursor, comme <strong>Claude</strong> ou <strong>GPT</strong>, ne sont pas inclus dans le forfait. Ils sont facturés aux tarifs publics de l'API et payés à partir d'un crédit prépayé. Les personnes disposant déjà d'un forfait Cursor peuvent le conserver. Le passage au nouvel abonnement est facultatif, mais Cursor indique que cette bascule est irréversible.</p>
<h2>Pourquoi c'est important</h2>
<p>Pour de nombreux développeurs, l'intérêt d'utiliser Cursor résidait dans l'accès facile aux modèles Claude et GPT au sein d'un même éditeur, pour un prix mensuel forfaitaire. Avec le nouveau regroupement, ce prix forfaitaire couvre Grok et les modèles propres à Cursor, tandis que Claude et GPT passent en facturation à l'usage. Si vous codez surtout avec Claude ou GPT, comparez ce que cela vous coûterait aux tarifs de l'API avant de basculer, ou conservez votre forfait Cursor actuel tant que c'est possible. Si les modèles propres de Grok et de Cursor vous suffisent, le forfait groupé ajoute X Premium et Grok en plus de l'éditeur.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('x-subscription-grok-cursor-bundle', 'pt', 'business', $t$Negócios$t$, '#f5a623', $t$xAI / Cursor$t$, $t$https://x.ai/news/x-subscription$t$, '2026-10-12', $t$Grok, Cursor e X Premium se fundem em uma única assinatura, e Claude e GPT agora custam extra no Cursor$t$, $t$A SpaceXSI lançou o The X Subscription em 12 de outubro, reunindo Grok, Cursor e X Premium em um único plano de $8 a $200 por mês, com um limite de uso semanal compartilhado. Novos clientes do Cursor já começam nesse plano, e Claude, GPT e outros modelos externos deixam de estar incluídos: passam a ser cobrados pelos preços de tabela da API, debitados de créditos pré-pagos.$t$, $t$<p>A SpaceXSI, empresa dona do Grok e do Cursor, lançou o <strong>The X Subscription</strong> em 12 de outubro. O plano reúne o Grok, o bot Grok, o <strong>Cursor</strong> e o X Premium em uma única assinatura, com cinco níveis: Free, Plus a $8, Premium a $30, Super a $100 e Ultra a $200 por mês.</p>
<h2>Um único limite de uso para Grok e Cursor</h2>
<p>Grok e Cursor agora compartilham a mesma cota de uso semanal. O que se gasta conversando com o Grok deixa de ser separado do que se gasta programando no Cursor, de modo que usuários intensos de um dos dois têm menos disponível para o outro.</p>
<h2>A pegadinha para usuários do Cursor</h2>
<p>Novos clientes do Cursor já começam no The X Subscription. As páginas de ajuda do Cursor informam que modelos de terceiros no Cursor, como <strong>Claude</strong> ou <strong>GPT</strong>, não estão incluídos no plano. Eles são cobrados pelos preços de tabela da API e pagos a partir de créditos pré-pagos. Quem já tem um plano do Cursor pode mantê-lo. A migração para a nova assinatura é opcional, mas o Cursor afirma que não pode ser revertida.</p>
<h2>Por que isso importa</h2>
<p>Para muitos desenvolvedores, o motivo de usar o Cursor era o acesso fácil aos modelos Claude e GPT dentro de um único editor, por um preço mensal fixo. No novo pacote, esse preço fixo cobre o Grok e os modelos próprios do Cursor, enquanto Claude e GPT passam a ser cobrados por uso. Para quem programa principalmente com Claude ou GPT, vale comparar quanto se gastaria nos preços da API antes de migrar, ou permanecer no plano atual do Cursor enquanto for possível. Para quem já se contenta com o Grok e os modelos próprios do Cursor, o pacote agrega o X Premium e o Grok ao editor.</p>$t$, NULL, true);
